effect.shader:
vec4 tex(vec2 p){ return texture2DCv(inputImg.texture, p); }
void main(){
vec2 uv = acScreenNorm;
vec2 st = 1.0 / max(acScreenSize, vec2(1.0));
vec4 src = tex(uv);
float rad = dir * 0.017453292519943295;
vec2 off = vec2(cos(rad), sin(rad)) * distance * st;
float occ = 0.0;
for (int i = 0; i < 16; i++){
  float a = 6.28318530718 * float(i) / 16.0;
  occ += tex(uv - off + vec2(cos(a), sin(a)) * spread * st).a;
}
occ /= 16.0;
float shadow = clamp(src.a - occ, 0.0, 1.0) * clamp(strength, 0.0, 1.0);
vec3 c = mix(src.rgb, shColor.rgb, clamp(shadow, 0.0, 1.0));
gl_FragColor = vec4(mix(src.rgb, c, mixAmt), src.a);
}
